  tmdb_id: ID,
  reacao: "amei" as const,
  titulo: tipo === "serie" ? "Série 1399" : "Filme 1399",
  ...(tipo && { tipo }),
});

const item = (usuarioId: string, tipo?: Tipo) => ({
  usuario_id: usuarioId,
  tmdb_id: ID,
  status: "assistido" as const,
  titulo: tipo === "serie" ? "Série 1399" : "Filme 1399",
  ...(tipo && { tipo }),
});

