11	/** Deixa a reação pedida (`null` apaga). Idempotente; título e gêneros vêm do TMDB. */
12	export async function definirReacao(
13	  supabase: ClienteSupabase,
14	  usuarioId: string,
15	  tmdbId: number,
16	  reacao: Reacao | null,
17	  buscarFilme: BuscarFilme = obterFilme,
18	): Promise<ResultadoDefinir<Reacao>> {
19	  const { data: atual, error: erroLeitura } = await supabase
20	    .from("reacoes")
21	    .select("reacao, titulo")
22	    .eq("tmdb_id", tmdbId)
23	    .maybeSingle();
24	  if (erroLeitura) {
25	    console.error("[reacoes] falha ao ler:", erroLeitura.code, erroLeitura.message);
26	    return { ok: false, erro: "banco" };
27	  }
28	  const anterior = atual?.reacao ?? null;
29	
30	  if (reacao === null) {
31	    if (atual) {
32	      const { error } = await supabase.from("reacoes").delete().eq("tmdb_id", tmdbId);
33	      if (error) {
34	        console.error("[reacoes] falha ao remover:", error.code, error.message);
35	        return { ok: false, erro: "banco" };
36	      }
37	    }
38	    return { ok: true, titulo: atual?.titulo ?? null, anterior, atual: null };
39	  }
40	
41	  if (atual && anterior === reacao) return { ok: true, titulo: atual.titulo, anterior, atual: reacao };
42	
43	  let filme: FilmeDetalhes | null;
44	  try {
45	    filme = await buscarFilme(tmdbId);
46	  } catch {
47	    return { ok: false, erro: "tmdb" };
48	  }
49	  if (!filme) return { ok: false, erro: "filme-nao-encontrado" };
50	
51	  const { error } = await supabase.from("reacoes").upsert({
52	    usuario_id: usuarioId,
53	    tmdb_id: tmdbId,
54	    reacao,
55	    titulo: filme.titulo,
56	    generos: filme.generos.map((genero) => genero.id),
57	  });
58	  if (error) {
59	    console.error("[reacoes] falha ao salvar:", error.code, error.message);
60	    return { ok: false, erro: "banco" };
61	  }
62	  return { ok: true, titulo: filme.titulo, anterior, atual: reacao };
63	}
